//
// This script is the entire "cloud" behind Workout Tracker's cloud backup. It runs in
// your own Google account and keeps the training log in your own Google Drive as the
// current backup, the copy that backup replaced, and one dated restore point per day,
// so the log never touches anyone else's server - not even the app author's.
//
// Deploy it in three steps:
//   1. Create a script project at script.google.com, paste this file over the whole of
//      Code.gs, then Save.
//   2. Deploy > New deployment > Web app. Execute as: Me. Who has access: Anyone.
//   3. Authorize when Google asks, then copy the deployment URL that ends in /exec.
// Paste that URL and your token into the app under Settings > Cloud Backup.
//
// Editing this script later: Deploy > Manage deployments > edit (the pencil) >
// Version: New version > Deploy. That keeps the same /exec URL, so the app keeps
// working. A second "New deployment" would hand you a different URL instead, and the
// app would still be talking to the old one.

var TOKEN = '__TOKEN__';

var FOLDER_NAME = 'Workout Tracker Backup';
var FILE_NAME = 'workout-backup.json';
var PREV_NAME = 'workout-backup.prev.json';
var SNAPSHOT_DAYS = 90; // daily restore points kept in the folder; 0 turns them off

// Pasting the /exec URL into a browser is the quickest way to tell a live deployment
// from a typo, so answer a GET in plain words rather than with an error.
function doGet() {
  return ContentService.createTextOutput(
    'Workout Tracker backup endpoint is running. Open the app, go to Settings > Cloud Backup and connect with this URL and your token.'
  ).setMimeType(ContentService.MimeType.TEXT);
}

// The app POSTs a JSON string with no Content-Type header, so postData.type is
// text/plain and only postData.contents is meaningful. Everything is wrapped so the
// client always gets JSON back, never an Apps Script HTML error page.
function doPost(e) {
  try {
    if (!e || !e.postData || !e.postData.contents) return json({ ok: false, error: 'Bad request' });
    var body = JSON.parse(e.postData.contents);
    if (!TOKEN || TOKEN.slice(0, 2) === '__' || TOKEN.length < 8)
      return json({ ok: false, error: 'Token not set - replace the placeholder in the TOKEN line of the script' });
    if (!body || body.token !== TOKEN) return json({ ok: false, error: 'Invalid token' });
    if (body.action === 'ping') return json(ping());
    if (body.action === 'restore') return json(restore());
    // 'sync' carries the whole snapshot as payload; 'event' describes one change but
    // ships the full state alongside it. Either way the stored file is replaced by the
    // snapshot, so type and payload are of no use here.
    if (body.action === 'sync') return json(writeSnapshot(body.payload, body.force === true));
    if (body.action === 'event') return json(writeSnapshot(body.state, body.force === true));
    return json({ ok: false, error: 'Unknown action' });
  } catch (err) {
    return json({ ok: false, error: String(err && err.message ? err.message : err) });
  }
}

function ping() {
  var folder = findFolder();
  var file = folder ? getFile(folder, FILE_NAME) : null;
  return { ok: true, hasBackup: !!file, updatedAt: file ? file.getLastUpdated().toISOString() : null };
}

function restore() {
  var folder = findFolder();
  var file = folder ? getFile(folder, FILE_NAME) : null;
  if (!file) return { ok: false, error: 'No backup yet' };
  var snapshot = readSnapshot(file);
  if (snapshot === null) return { ok: false, error: 'Stored backup is unreadable' };
  return snapshot;
}

// An upload is destructive: it replaces the current backup, and automatic uploads never
// ask first. Hence the shape check, the empty-over-non-empty refusal, the one-step undo
// copy and the dated daily files.
function writeSnapshot(snapshot, force) {
  if (!snapshot || typeof snapshot !== 'object' || isArray(snapshot) || !isArray(snapshot.workouts))
    return { ok: false, error: 'Snapshot is not in the expected format' };
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(10000)) return { ok: false, error: 'Backup is busy, try again in a moment' };
  try {
    var folder = getFolder();
    var file = getFile(folder, FILE_NAME);
    if (!force && isEmpty(snapshot)) {
      // A stored file we cannot parse is not evidence of a log worth protecting, so it
      // does not block the write - the previous copy is still taken below.
      var stored = file ? readSnapshot(file) : null;
      if (stored && !isEmpty(stored))
        return {
          ok: false,
          error: 'Refused: this would replace a backup that has workouts with an empty one. Use Sync Now in the app to overwrite it on purpose.'
        };
    }
    var content = JSON.stringify(snapshot);
    if (file) {
      keepPrevious(folder, file);
      file.setContent(content);
    } else {
      file = folder.createFile(FILE_NAME, content, 'application/json');
    }
    // The backup is written by now. A Drive hiccup while filing the day's copy must not
    // report that write as failed: the app would retry an upload that had landed, rotating
    // the prev copy over the content it was keeping. The next upload files the copy instead.
    if (SNAPSHOT_DAYS > 0) {
      try {
        keepDaily(folder, content);
      } catch (err) {
        // The upload still succeeded. Logged so that a persistent failure shows up in the
        // project's Executions panel instead of silently leaving no dated files behind.
        console.error('Daily restore point not written: ' + err);
      }
    }
    return { ok: true, updatedAt: file.getLastUpdated().toISOString() };
  } finally {
    lock.releaseLock();
  }
}

// One step of undo for a bad upload: the content being replaced is copied aside first.
function keepPrevious(folder, file) {
  var old = file.getBlob().getDataAsString();
  var prev = getFile(folder, PREV_NAME);
  if (prev) prev.setContent(old);
  else folder.createFile(PREV_NAME, old, 'application/json');
}

// One restore point per calendar day (the script's time zone): the first upload of a day
// is kept as workout-backup.YYYY-MM-DD.json and every later upload that day leaves it
// alone, so the dated file holds the log as it stood at the day's first save - in practice
// where the previous day ended.
function keepDaily(folder, content) {
  var today = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd');
  var name = 'workout-backup.' + today + '.json';
  if (getFile(folder, name)) return;
  folder.createFile(name, content, 'application/json');
  pruneDaily(folder, today);
}

// Restore points older than SNAPSHOT_DAYS go to the Drive trash when a new day's file is
// created: a file exactly SNAPSHOT_DAYS old stays, the day after it goes, and an idle
// folder keeps what it has until the next upload. The age comes from the date in the name
// rather than getDateCreated, so a file restored out of the trash still expires on its own
// date. The pattern matches only the dated files - workout-backup.json and
// workout-backup.prev.json are never touched here.
function pruneDaily(folder, today) {
  var pattern = /^workout-backup\.(\d{4})-(\d{2})-(\d{2})\.json$/;
  var parts = pattern.exec('workout-backup.' + today + '.json');
  if (!parts) return;
  var cutoff = dayValue(parts) - SNAPSHOT_DAYS * 86400000;
  var it = folder.getFiles();
  while (it.hasNext()) {
    var file = it.next();
    var m = pattern.exec(file.getName());
    if (m && !file.isTrashed() && dayValue(m) < cutoff) file.setTrashed(true);
  }
}

function dayValue(m) {
  return Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}

// Mirrors isEmptySnapshot in the app's src/sync.js exactly. A log the user emptied into
// the Trash still has 'deleted' entries and must be allowed to upload.
function isEmpty(s) {
  if (!s || typeof s !== 'object') return true;
  return (
    (!s.workouts || s.workouts.length === 0) && (!s.deleted || s.deleted.length === 0) && (!s.bodyWeights || s.bodyWeights.length === 0)
  );
}

// Reads never create anything, so two first-time pings cannot race into two folders;
// the folder is only ever created inside the write lock. A folder the user has trashed is
// passed over like a trashed file, so the next write starts a fresh one.
function findFolder() {
  var it = DriveApp.getFoldersByName(FOLDER_NAME);
  while (it.hasNext()) {
    var f = it.next();
    if (!f.isTrashed()) return f;
  }
  return null;
}

function getFolder() {
  return findFolder() || DriveApp.createFolder(FOLDER_NAME);
}

// Drive's by-name iterators also hand back files sitting in the trash. Without this check
// a backup the user had thrown away would be written into, and counted, as if it were
// still there.
function getFile(folder, name) {
  var it = folder.getFilesByName(name);
  while (it.hasNext()) {
    var f = it.next();
    if (!f.isTrashed()) return f;
  }
  return null;
}

function readSnapshot(file) {
  try {
    return JSON.parse(file.getBlob().getDataAsString());
  } catch (err) {
    return null;
  }
}

function isArray(v) {
  return Object.prototype.toString.call(v) === '[object Array]';
}

function json(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}
